"""Generate src/hermes_printable.rs: the code points CPython's str.isprintable() rejects.

Run with the CI Python (3.12) so the table matches the interpreter that recorded
the vectors:  python generate_printable_table.py ../../src/hermes_printable.rs
"""

from __future__ import annotations

import sys
import unicodedata
from pathlib import Path

NON_PRINTABLE = {"Cc", "Cf", "Cs", "Co", "Cn", "Zl", "Zp", "Zs"}


def ranges() -> list[tuple[int, int]]:
    found: list[tuple[int, int]] = []
    start = None
    for code in range(0x110000):
        char = chr(code)
        hidden = char != " " and unicodedata.category(char) in NON_PRINTABLE
        if hidden and start is None:
            start = code
        if not hidden and start is not None:
            found.append((start, code - 1))
            start = None
    if start is not None:
        found.append((start, 0x10FFFF))
    return found


def render() -> str:
    pairs = ranges()
    lines = [
        "//! Generated by testdata/hermes/generate_printable_table.py; do not edit.",
        f"//! Code points rejected by CPython `str.isprintable()` (Unicode {unicodedata.unidata_version}).",
        "",
        "#[rustfmt::skip]",
        f"const NON_PRINTABLE: [(u32, u32); {len(pairs)}] = [",
    ]
    row: list[str] = []
    for low, high in pairs:
        row.append(f"(0x{low:x}, 0x{high:x}),")
        if len(row) == 5:
            lines.append("    " + " ".join(row))
            row = []
    if row:
        lines.append("    " + " ".join(row))
    lines += [
        "];",
        "",
        "/// `str.isprintable()` for one character.",
        "pub(crate) fn is_printable(ch: char) -> bool {",
        "    let code = ch as u32;",
        "    NON_PRINTABLE",
        "        .binary_search_by(|&(low, high)| {",
        "            if code < low {",
        "                std::cmp::Ordering::Greater",
        "            } else if code > high {",
        "                std::cmp::Ordering::Less",
        "            } else {",
        "                std::cmp::Ordering::Equal",
        "            }",
        "        })",
        "        .is_err()",
        "}",
        "",
    ]
    return "\n".join(lines)


if __name__ == "__main__":
    Path(sys.argv[1]).write_text(render(), encoding="utf-8")
